<script>
    let items = [];
    let itemCount = 0;
    let editingId = null;

    // Load saved data immediately on open
    window.addEventListener('DOMContentLoaded', () => {
        const savedItems = localStorage.getItem('garageSaleItems');
        const savedCount = localStorage.getItem('garageSaleItemCount');

        if (savedItems) {
            items = JSON.parse(savedItems);
        }
        if (savedCount) {
            itemCount = parseInt(savedCount, 10);
        }

        updateUI();
    });

    function saveToLocalStorage() {
        localStorage.setItem('garageSaleItems', JSON.stringify(items));
        localStorage.setItem('garageSaleItemCount', itemCount.toString());
    }

    function addItem(event) {
        event.preventDefault();

        const nameInput = document.getElementById('itemName');
        const priceInput = document.getElementById('itemPrice');

        itemCount++;
        const item = {
            id: itemCount,
            name: nameInput.value.trim(),
            price: parseFloat(priceInput.value).toFixed(2)
        };

        items.push(item);
        saveToLocalStorage();
        updateUI();

        nameInput.value = '';
        priceInput.value = '';
        nameInput.focus();
    }

    function deleteItem(id) {
        items = items.filter(item => item.id !== id);
        saveToLocalStorage();
        updateUI();
    }

    function startEdit(id) {
        editingId = id;
        updateUI();
    }

    function saveEdit(id) {
        const nameInput = document.getElementById(`edit-name-${id}`);
        const priceInput = document.getElementById(`edit-price-${id}`);

        const item = items.find(item => item.id === id);
        if (item) {
            item.name = nameInput.value.trim() || item.name;
            item.price = parseFloat(priceInput.value || 0).toFixed(2);
        }

        editingId = null;
        saveToLocalStorage();
        updateUI();
    }

    function cancelEdit() {
        editingId = null;
        updateUI();
    }

    function clearAllItems() {
        if (confirm("Are you sure you want to permanently delete all items and tags from this sheet?")) {
            items = [];
            itemCount = 0;
            editingId = null;
            localStorage.removeItem('garageSaleItems');
            localStorage.removeItem('garageSaleItemCount');
            updateUI();
        }
    }

    function updateUI() {
        const tagsContainer = document.getElementById('tagsContainer');
        const inventoryBody = document.getElementById('inventoryBody');
        const totalAmount = document.getElementById('totalAmount');

        tagsContainer.innerHTML = '';
        inventoryBody.innerHTML = '';

        let total = 0;

        items.forEach(item => {
            // Render Tag
            const tagHtml = `
                <div class="tag">
                    <div class="tag-title">${item.name}</div>
                    <div class="tag-price">$${item.price}</div>
                    <div style="font-size: 0.65rem; color: #64748b;">#${item.id}</div>
                </div>
            `;
            tagsContainer.insertAdjacentHTML('beforeend', tagHtml);

            // Render Table Row (Normal vs Edit Mode)
            let rowHtml = '';
            if (editingId === item.id) {
                rowHtml = `
                    <tr>
                        <td>#${item.id}</td>
                        <td><input type="text" id="edit-name-${item.id}" class="inline-edit-input" value="${item.name}"></td>
                        <td class="text-right"><input type="number" id="edit-price-${item.id}" class="inline-edit-input text-right" step="0.25" min="0" value="${item.price}"></td>
                        <td class="text-right no-print">
                            <button class="btn btn-sm btn-save" onclick="saveEdit(${item.id})">Save</button>
                            <button class="btn btn-sm btn-edit" onclick="cancelEdit()">X</button>
                        </td>
                    </tr>
                `;
            } else {
                rowHtml = `
                    <tr>
                        <td>#${item.id}</td>
                        <td>${item.name}</td>
                        <td class="text-right">$${item.price}</td>
                        <td class="text-right no-print">
                            <button class="btn btn-sm btn-edit" onclick="startEdit(${item.id})">Edit</button>
                            <button class="btn btn-sm btn-delete" onclick="deleteItem(${item.id})">Delete</button>
                        </td>
                    </tr>
                `;
            }
            inventoryBody.insertAdjacentHTML('beforeend', rowHtml);

            total += parseFloat(item.price);
        });

        totalAmount.textContent = `$${total.toFixed(2)}`;
    }
</script>

</body>
</html>

