<div class="container">
    <header class="no-print">
        <h1>Garage Sale Manager</h1>
        <div class="btn-group">
            <button class="btn btn-clear" onclick="clearAllItems()">Clear All</button>
            <button class="btn btn-sec" onclick="copySummaryText()">Copy Summary</button>
            <button class="btn btn-sec" onclick="downloadCSV()">Export CSV</button>
            <button class="btn btn-print" onclick="window.print()">Print Tags & Sheets</button>
        </div>
    </header>

    <div class="grid">
        <div class="panel no-print">
            <h2>Add New Item</h2>
            <form id="itemForm" onsubmit="addItem(event)">
                <div class="form-group">
                    <label for="itemName">Item Description</label>
                    <input type="text" id="itemName" placeholder="e.g., Mountain Bike" required autofocus>
                </div>
                <div class="form-group">
                    <label for="itemPrice">Price ($)</label>
                    <input type="number" id="itemPrice" step="0.25" min="0" placeholder="0.00" required>
                </div>
                <button type="submit" class="btn" style="width: 100%; margin-top: 8px;">Add Item</button>
            </form>
        </div>

        <div class="preview-section">
            <div class="panel">
                <h2>Price Tags</h2>
                <div class="tags-container" id="tagsContainer"></div>
            </div>

            <div class="panel page-break">
                <h2>Inventory & Total Sheet</h2>
                <table>
                    <thead>
                        <tr>
                            <th class="no-print" style="width: 45px; text-align: center;">Sold</th>
                            <th style="width: 70px;">Item #</th>
                            <th>Description</th>
                            <th class="text-right" style="width: 100px;">Price</th>
                            <th class="text-right no-print" style="width: 130px;">Actions</th>
                        </tr>
                    </thead>
                    <tbody id="inventoryBody"></tbody>
                    <tfoot>
                        <tr class="total-row">
                            <td class="no-print"></td>
                            <td colspan="2" class="text-right-print">Total Inventory Value:</td>
                            <td class="text-right" id="totalAmount">$0.00</td>
                            <td class="no-print"></td>
                        </tr>
                        <tr class="total-row collected-row">
                            <td class="no-print"></td>
                            <td colspan="2" class="text-right-print">Actual Cash Collected:</td>
                            <td class="text-right" id="collectedAmount">$0.00</td>
                            <td class="no-print"></td>
                        </tr>
                        <tr class="total-row" style="color: #64748b;">
                            <td class="no-print"></td>
                            <td colspan="2" class="text-right-print">Remaining Value on Tables:</td>
                            <td class="text-right" id="remainingAmount">$0.00</td>
                            <td class="no-print"></td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </div>
    </div>
</div>

<script>
    let items = [];
    let itemCount = 0;
    let editingId = null;

    window.addEventListener('DOMContentLoaded', () => {
        const savedItems = localStorage.getItem('garageSaleItems');
        const savedCount = localStorage.getItem('garageSaleItemCount');

        if (savedItems) {
            items = JSON.parse(savedItems);
        }
        if (savedCount) {
            itemCount = parseInt(savedCount, 10);
        }

        updateUI();
    });

    function saveToLocalStorage() {
        localStorage.setItem('garageSaleItems', JSON.stringify(items));
        localStorage.setItem('garageSaleItemCount', itemCount.toString());
    }

    function addItem(event) {
        event.preventDefault();

        const nameInput = document.getElementById('itemName');
        const priceInput = document.getElementById('itemPrice');

        itemCount++;
        const item = {
            id: itemCount,
            name: nameInput.value.trim(),
            price: parseFloat(priceInput.value).toFixed(2),
            sold: false
        };

        items.push(item);
        saveToLocalStorage();
        updateUI();

        nameInput.value = '';
        priceInput.value = '';
        nameInput.focus();
    }

    function toggleSold(id) {
        const item = items.find(item => item.id === id);
        if (item) {
            item.sold = !item.sold;
            saveToLocalStorage();
            updateUI();
        }
    }

    function deleteItem(id) {
        items = items.filter(item => item.id !== id);
        saveToLocalStorage();
        updateUI();
    }

    function startEdit(id) {
        editingId = id;
        updateUI();
    }

    function saveEdit(id) {
        const nameInput = document.getElementById(`edit-name-${id}`);
        const priceInput = document.getElementById(`edit-price-${id}`);

        const item = items.find(item => item.id === id);
        if (item) {
            item.name = nameInput.value.trim() || item.name;
            item.price = parseFloat(priceInput.value || 0).toFixed(2);
        }

        editingId = null;
        saveToLocalStorage();
        updateUI();
    }

    function cancelEdit() {
        editingId = null;
        updateUI();
    }

    function clearAllItems() {
        if (confirm("Are you sure you want to permanently delete all items and tags from this sheet?")) {
            items = [];
            itemCount = 0;
            editingId = null;
            localStorage.removeItem('garageSaleItems');
            localStorage.removeItem('garageSaleItemCount');
            updateUI();
        }
    }

    function copySummaryText() {
        if (items.length === 0) {
            alert("No items to copy.");
            return;
        }

        let totalVal = 0, cashColl = 0, remainVal = 0;
        let textLines = ["--- GARAGE SALE INVENTORY SUMMARY ---"];

        items.forEach(item => {
            const statusStr = item.sold ? "[SOLD]" : "[AVAILABLE]";
            textLines.push(`#${item.id}: ${item.name} - $${item.price} ${statusStr}`);

            const priceNum = parseFloat(item.price);
            totalVal += priceNum;
            if (item.sold) cashColl += priceNum; else remainVal += priceNum;
        });

        textLines.push("-------------------------------------");
        textLines.push(`Total Inventory Value: $${totalVal.toFixed(2)}`);
        textLines.push(`Actual Cash Collected: $${cashColl.toFixed(2)}`);
        textLines.push(`Remaining On Tables:   $${remainVal.toFixed(2)}`);

        const fullText = textLines.join("\n");

        navigator.clipboard.writeText(fullText).then(() => {
            alert("Summary copied to clipboard!");
        }).catch(err => {
            alert("Failed to copy text.");
        });
    }

    function downloadCSV() {
        if (items.length === 0) {
            alert("No items to export.");
            return;
        }

        let csvContent = "data:text/csv;charset=utf-8,";
        csvContent += "Item Number,Description,Price,Status\n";

        let totalVal = 0, cashColl = 0, remainVal = 0;
        items.forEach(item => {
            const cleanName = item.name.replace(/"/g, '""');
            const status = item.sold ? "Sold" : "Available";
            csvContent += `"${item.id}","${cleanName}","${item.price}","${status}"\n`;

            const priceNum = parseFloat(item.price);
            totalVal += priceNum;
            if (item.sold) cashColl += priceNum; else remainVal += priceNum;
        });

        csvContent += `\n"","Total Inventory Value","${totalVal.toFixed(2)}"\n`;
        csvContent += `"","Actual Cash Collected","${cashColl.toFixed(2)}"\n`;
        csvContent += `"","Remaining Value","${remainVal.toFixed(2)}"\n`;

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `garage_sale_tracker_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);

        link.click();
        document.body.removeChild(link);
    }

    function updateUI() {
        const tagsContainer = document.getElementById('tagsContainer');
        const inventoryBody = document.getElementById('inventoryBody');
        const totalAmount = document.getElementById('totalAmount');
        const collectedAmount = document.getElementById('collectedAmount');
        const remainingAmount = document.getElementById('remainingAmount');

        tagsContainer.innerHTML = '';
        inventoryBody.innerHTML = '';

        let totalVal = 0;
        let cashCollected = 0;
        let remainingVal = 0;

        items.forEach(item => {
            const priceNum = parseFloat(item.price);
            totalVal += priceNum;
            if (item.sold) {
                cashCollected += priceNum;
            } else {
                remainingVal += priceNum;
            }

            // Tags remain uncrossed and clean even if sold
            const tagHtml = `
                <div class="tag">
                    <div class="tag-title">${item.name}</div>
                    <div class="tag-price">$${item.price}</div>
                    <div style="font-size: 0.65rem; color: #64748b;">#${item.id}</div>
                </div>
            `;
            tagsContainer.insertAdjacentHTML('beforeend', tagHtml);

            let rowHtml = '';
            const rowClass = item.sold ? 'class="row-sold"' : '';
            const isChecked = item.sold ? 'checked' : '';

            if (editingId === item.id) {
                rowHtml = `
                    <tr>
                        <td class="no-print" style="text-align: center;"><input type="checkbox" class="chk-sold" disabled ${isChecked}></td>
                        <td>#${item.id}</td>
                        <td><input type="text" id="edit-name-${item.id}" class="inline-edit-input" value="${item.name}"></td>
                        <td class="text-right"><input type="number" id="edit-price-${item.id}" class="inline-edit-input text-right" step="0.25" min="0" value="${item.price}"></td>
                        <td class="text-right no-print">
                            <button class="btn btn-sm btn-save" onclick="saveEdit(${item.id})">Save</button>
                            <button class="btn btn-sm btn-edit" onclick="cancelEdit()">X</button>
                        </td>
                    </tr>
                `;
            } else {
                rowHtml = `
                    <tr ${rowClass}>
                        <td class="no-print" style="text-align: center;">
                            <input type="checkbox" class="chk-sold" onchange="toggleSold(${item.id})" ${isChecked}>
                        </td>
                        <td>#${item.id}</td>
                        <td>${item.name}</td>
                        <td class="text-right">$${item.price}</td>
                        <td class="text-right no-print">
                            <button class="btn btn-sm btn-edit" onclick="startEdit(${item.id})">Edit</button>
                            <button class="btn btn-sm btn-delete" onclick="deleteItem(${item.id})">Delete</button>
                        </td>
                    </tr>
                `;
            }
            inventoryBody.insertAdjacentHTML('beforeend', rowHtml);
        });

        totalAmount.textContent = `$${totalVal.toFixed(2)}`;
        collectedAmount.textContent = `$${cashCollected.toFixed(2)}`;
        remainingAmount.textContent = `$${remainingVal.toFixed(2)}`;
    }
</script>

</body>
</html>

